-- 0061 Versioned job packets, what each staff member last viewed, and every print or PDF export (TSK-0069; HH-PKT-01,
-- HH-PKT-02, HH-PKT-07, HH-DATA-08, HH-OFF-02, T28, T43, T44, ENT-JobPacket, ENT-AccessInstructionSecret, ENT-AuditEvent,
-- OWN-DEC-121, OWN-DEC-40, RULE-SAFETY-GATES, RULE-SERVER-AUTHZ).
-- - job_packets: one immutable version of a job's packet (ENT-JobPacket), generated by the server from the stored
--   records (apps/server/src/modules/packets/content.ts): the job and its work packages, the live work visits with
--   their windows and confirmed teams, the property's site-access and occupant details with their sources and last
--   confirmations, the accepted scope snapshot without any price, prior customer photo references, the SOP version
--   pinned on each work package, the blocking holds, the reserved equipment and the deposit state. A new version is
--   written only when that content differs from the job's latest version, numbered one after it, with what changed
--   and whether a change is critical (scope, holds, SOP version, assignment, site access: HH-PKT-02, HH-DATA-08).
--   The content never holds an access code (only a code's kind, label and confirmation, so the packet can say one is
--   revealed separately, online, in the audited flow of TSK-0045) and never the service address itself (the address
--   version only; the view reads the address). Append-only: versions are never changed or deleted.
-- - job_packet_views: which version a staff member viewed and when, so the packet shows "What changed since you
--   reviewed this?" against the version that person last viewed. A view is not an acknowledgment (TSK-0072): it
--   releases nothing and passes no gate. Append-only.
-- - job_packet_exports: every print and PDF export: who, when, which version, and the job's latest version at that
--   moment (an export of an older version is stale). Exports never contain an access code (HH-PKT-07). Append-only;
--   each is also audited (job_packet.export).

CREATE TABLE work.job_packets (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id         uuid NOT NULL,
  project_id     uuid NOT NULL,
  version        integer NOT NULL CHECK (version >= 1),
  content        jsonb NOT NULL CHECK (jsonb_typeof(content) = 'object'),
  -- SHA-256 of the canonical content.
  content_sha256 text NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
  -- What changed against the previous version, item by item (empty for version 1), and whether any is critical.
  changes        jsonb NOT NULL CHECK (jsonb_typeof(changes) = 'array'),
  critical       boolean NOT NULL,
  generated_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (job_id, version),
  UNIQUE (id, job_id, version),
  CONSTRAINT job_packets_job FOREIGN KEY (job_id, project_id) REFERENCES work.jobs (id, project_id),
  CONSTRAINT job_packets_first CHECK (version > 1 OR (NOT critical AND changes = '[]'::jsonb)),
  -- The content never carries an access code's value or sealed value (HH-PKT-07, HH-OFF-02).
  CONSTRAINT job_packets_no_secret CHECK (NOT content::text ~* '"(sealed_?value|value_sealed|code_value|secret)"\s*:')
);
CREATE INDEX job_packets_latest ON work.job_packets (job_id, version DESC);
COMMENT ON TABLE work.job_packets IS
  'Immutable versions of a job packet (ENT-JobPacket): content without access codes or prices, changes, critical flag.';

-- A version is numbered one after the job's latest and differs from it; the job is locked by the writer (an advisory
-- lock per job, apps/server/src/modules/packets/content.ts), and the unique (job_id, version) refuses a race.
CREATE FUNCTION work.job_packet_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  latest_version integer;
  latest_sha     text;
BEGIN
  SELECT version, content_sha256 INTO latest_version, latest_sha
    FROM work.job_packets WHERE job_id = NEW.job_id ORDER BY version DESC LIMIT 1;
  IF NEW.version <> COALESCE(latest_version, 0) + 1 THEN
    RAISE EXCEPTION 'a packet version follows the latest one' USING ERRCODE = 'check_violation';
  END IF;
  IF latest_sha IS NOT NULL AND latest_sha = NEW.content_sha256 THEN
    RAISE EXCEPTION 'a new packet version changes the content' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER job_packets_guard BEFORE INSERT ON work.job_packets
  FOR EACH ROW EXECUTE FUNCTION work.job_packet_guard();
CREATE TRIGGER job_packets_append_only BEFORE UPDATE OR DELETE ON work.job_packets
  FOR EACH ROW EXECUTE FUNCTION platform.reject_append_only_change();

CREATE TABLE work.job_packet_views (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  packet_id     uuid NOT NULL,
  job_id        uuid NOT NULL,
  version       integer NOT NULL,
  staff_user_id uuid NOT NULL REFERENCES identity.staff_users (id),
  viewed_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT job_packet_views_packet FOREIGN KEY (packet_id, job_id, version)
    REFERENCES work.job_packets (id, job_id, version)
);
CREATE INDEX job_packet_views_last ON work.job_packet_views (job_id, staff_user_id, viewed_at DESC);
CREATE TRIGGER job_packet_views_append_only BEFORE UPDATE OR DELETE ON work.job_packet_views
  FOR EACH ROW EXECUTE FUNCTION platform.reject_append_only_change();
COMMENT ON TABLE work.job_packet_views IS
  'Which packet version a staff member viewed and when (the "since you reviewed" baseline); not an acknowledgment.';

CREATE TABLE work.job_packet_exports (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  packet_id      uuid NOT NULL,
  job_id         uuid NOT NULL,
  version        integer NOT NULL,
  -- The job's latest packet version when the export was made: an export of an older version is stale.
  latest_version integer NOT NULL,
  staff_user_id  uuid NOT NULL REFERENCES identity.staff_users (id),
  format         text NOT NULL CHECK (format IN ('print', 'pdf')),
  request_id     text NOT NULL CHECK (char_length(request_id) BETWEEN 1 AND 200),
  exported_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (latest_version >= version),
  CONSTRAINT job_packet_exports_packet FOREIGN KEY (packet_id, job_id, version)
    REFERENCES work.job_packets (id, job_id, version)
);
CREATE INDEX job_packet_exports_job ON work.job_packet_exports (job_id, exported_at DESC);
CREATE TRIGGER job_packet_exports_append_only BEFORE UPDATE OR DELETE ON work.job_packet_exports
  FOR EACH ROW EXECUTE FUNCTION platform.reject_append_only_change();
COMMENT ON TABLE work.job_packet_exports IS
  'Every print and PDF export of a job packet: who, when, which version, the latest version then (HH-PKT-07).';
